package dev.clio.app.engine

/**
 * Thin wrapper around the UniFFI bindings (package `uniffi.clio_ffi`, generated by build-rust.sh).
 * Falls back gracefully if the native library is missing (e.g. in JVM previews/screenshot tests).
 */
object Engine {
    val version: String by lazy {
        runCatching { uniffi.clio_ffi.engineVersion() }.getOrElse { "preview" }
    }

    fun presets(): List<uniffi.clio_ffi.ExportPreset> =
        runCatching { uniffi.clio_ffi.exportPresets() }.getOrElse { emptyList() }

    fun newProject(name: String, width: UInt = 1080u, height: UInt = 1920u): uniffi.clio_ffi.ClioProject? =
        runCatching { uniffi.clio_ffi.ClioProject(name, width, height) }.getOrNull()

    /** Retimes caption cue `index` (engine clamps to the video and neighbours, rescales words). Null on error. */
    fun retimeCaption(p: uniffi.clio_ffi.ClioProject, index: Int, startMs: Long, endMs: Long): uniffi.clio_ffi.Caption? =
        runCatching { p.retimeCaption(index.coerceAtLeast(0).toUInt(), startMs.coerceAtLeast(0).toULong(), endMs.coerceAtLeast(0).toULong()) }.getOrNull()

    data class Cap(val startMs: Long, val endMs: Long, val text: String, val words: List<uniffi.clio_ffi.CaptionWord> = emptyList()) {
        fun toFfi() = uniffi.clio_ffi.Caption(startMs.toULong(), endMs.toULong(), text, words)
    }

    /** STUB on the Rust side for now (placeholder cues); see crates/ffi-mobile generate_captions. */
    fun generateCaptions(durationMs: Long): List<Cap> =
        runCatching { uniffi.clio_ffi.generateCaptions(durationMs.toULong()).map { Cap(it.startMs.toLong(), it.endMs.toLong(), it.text) } }
            .getOrElse { listOf(Cap(0, 2900, "Olá, bem-vindo ao Clio"), Cap(3000, 5900, "Hoje vamos editar juntos"), Cap(6000, 8900, "Corte, ajuste e compartilhe")) }

    /** REAL: SRT/WebVTT writer from the FilmCraft captions crate. */
    fun captionsToSrt(caps: List<Cap>): String =
        runCatching { uniffi.clio_ffi.captionsToFile(caps.map { it.toFfi() }, false) }
            .getOrElse { "" }
}
